BEGIN;

-- ── 1. New type: Research ──────────────────────────────────────────────
INSERT INTO types (name, position, is_in_roadmap, is_milestone, is_default, color_id, created_at, updated_at, is_standard)
SELECT 'Research', 8, true, false, false, 9, now(), now(), false
WHERE NOT EXISTS (SELECT 1 FROM types WHERE name = 'Research');

-- ── 2. New statuses: Blocked, In review ────────────────────────────────
INSERT INTO statuses (name, is_closed, is_default, position, created_at, updated_at, color_id)
SELECT 'Blocked', false, false, 15, now(), now(), 8
WHERE NOT EXISTS (SELECT 1 FROM statuses WHERE name = 'Blocked');

INSERT INTO statuses (name, is_closed, is_default, position, created_at, updated_at, color_id)
SELECT 'In review', false, false, 16, now(), now(), 7
WHERE NOT EXISTS (SELECT 1 FROM statuses WHERE name = 'In review');

-- ── 3. Project types for kainos-logos: Task, Epic, Bug, Research ──────
DELETE FROM projects_types WHERE project_id = 14;
INSERT INTO projects_types (project_id, type_id)
SELECT 14, id FROM types WHERE name IN ('Task', 'Epic', 'Bug', 'Research');

-- ── 4. Workflows ───────────────────────────────────────────────────────
DO $$
DECLARE
  r_id    INT := (SELECT id FROM types   WHERE name = 'Research');
  b_id    INT := (SELECT id FROM statuses WHERE name = 'Blocked');
  ir_id   INT := (SELECT id FROM statuses WHERE name = 'In review');
  t INT; role INT; used_statuses INT[];
BEGIN
  -- Research: full transition graph over all statuses (incl. new ones)
  FOR role IN SELECT unnest(ARRAY[4, 6, 7]) LOOP
    INSERT INTO workflows (type_id, old_status_id, new_status_id, role_id)
    SELECT r_id, a.id, b.id, role
    FROM statuses a CROSS JOIN statuses b
    ON CONFLICT DO NOTHING;
  END LOOP;

  -- Task(1), Epic(5), Bug(7): connect Blocked & In review to the statuses
  -- each type can already reach, in both directions, plus self-loops
  FOR t IN SELECT unnest(ARRAY[1, 5, 7]) LOOP
    FOR role IN SELECT unnest(ARRAY[4, 6, 7]) LOOP
      SELECT array_agg(DISTINCT s.id) INTO used_statuses
      FROM (
        SELECT new_status_id AS id FROM workflows WHERE type_id = t
        UNION
        SELECT old_status_id AS id FROM workflows WHERE type_id = t
      ) s;

      -- used status → Blocked / In review
      INSERT INTO workflows (type_id, old_status_id, new_status_id, role_id)
      SELECT t, us, ns, role
      FROM unnest(used_statuses || ARRAY[b_id, ir_id]) AS us
      CROSS JOIN unnest(ARRAY[b_id, ir_id]) AS ns
      WHERE us <> ns;

      -- Blocked / In review → used status
      INSERT INTO workflows (type_id, old_status_id, new_status_id, role_id)
      SELECT t, ns, us, role
      FROM unnest(used_statuses || ARRAY[b_id, ir_id]) AS us
      CROSS JOIN unnest(ARRAY[b_id, ir_id]) AS ns
      WHERE us <> ns;
    END LOOP;
  END LOOP;
END $$;

COMMIT;

